import { describe, expect, it } from 'vitest'
import {
  buildMerkleTree,
  getConsistencyProofRFC9162,
  verifyConsistencyProofRFC9162,
} from './merkleTree'
import { SAMPLE_CERTS } from '../data/mtcConstants'

// Original published Google CT samples; no expected roots generated by this implementation.
// https://github.com/google/certificate-transparency/blob/0fe5116f42890853e9fcf5120f1f5129d64f64ea/python/ct/crypto/merkle_test.py
// MerkleVerifierTest.sha256_proofs (historical RFC 6962 construction, retained by RFC 9162).
const referenceProofs: [number, number, string, string, string[]][] = [
  [
    1,
    1,
    '6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d',
    '6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d',
    [],
  ],
  [
    1,
    8,
    '6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d',
    '5dc9da79a70659a9ad559cb701ded9a2ab9d823aad2f4960cfe370eff4604328',
    [
      '96a296d224f285c67bee93c30f8a309157f0daa35dc5b87e410b78630a09cfc7',
      '5f083f0a1a33ca076a95279832580db3e0ef4584bdff1f54c8a360f50de3031e',
      '6b47aaf29ee3c2af9af889bc1fb9254dabd31177f16232dd6aab035ca39bf6e4',
    ],
  ],
  [
    6,
    8,
    '76e67dadbcdf1e10e1b74ddc608abd2f98dfb16fbce75277b5232a127f2087ef',
    '5dc9da79a70659a9ad559cb701ded9a2ab9d823aad2f4960cfe370eff4604328',
    [
      '0ebc5d3437fbe2db158b9f126a1d118e308181031d0a949f8dededebc558ef6a',
      'ca854ea128ed050b41b35ffc1b87b8eb2bde461e9e3b5596ece6b9d5975a0ae0',
      'd37ee418976dd95753c1c73862b9398fa2a2cf9b4ff0fdfe8b30cd95209614b7',
    ],
  ],
  [
    2,
    5,
    'fac54203e7cc696cf0dfcb42c92a1d9dbaf70ad9e621f4bd8d98662f00e3c125',
    '4e3bbb1f7b478dcfe71fb631631519a3bca12c9aefca1612bfce4c13a86264d4',
    [
      '5f083f0a1a33ca076a95279832580db3e0ef4584bdff1f54c8a360f50de3031e',
      'bc1a0643b12e4d2d7c77918f44e0f4f79a838b6cf9ec5b5c283e1f4d88599e6b',
    ],
  ],
]

describe('Merkle consistency verification', () => {
  for (const [oldSize, newSize, oldRoot, newRoot, proof] of referenceProofs) {
    const input = { oldSize, newSize, oldRoot, newRoot, proof }
    it(`accepts the published ${oldSize}-to-${newSize} proof and rejects forged roots`, async () => {
      expect(await verifyConsistencyProofRFC9162(input)).toBe(true)
      expect(await verifyConsistencyProofRFC9162({ ...input, newRoot: '00'.repeat(32) })).toBe(
        false
      )
      expect(await verifyConsistencyProofRFC9162({ ...input, oldRoot: '00'.repeat(32) })).toBe(
        false
      )
    })
    if (proof.length) {
      it(`rejects altered, missing, extended and mis-sized ${oldSize}-to-${newSize} proofs`, async () => {
        expect(
          await verifyConsistencyProofRFC9162({
            ...input,
            proof: ['00'.repeat(32), ...proof.slice(1)],
          })
        ).toBe(false)
        expect(await verifyConsistencyProofRFC9162({ ...input, proof: proof.slice(1) })).toBe(false)
        expect(
          await verifyConsistencyProofRFC9162({ ...input, proof: [...proof, '00'.repeat(32)] })
        ).toBe(false)
        expect(await verifyConsistencyProofRFC9162({ ...input, oldSize: oldSize + 1 })).toBe(false)
        if (proof.length > 1)
          expect(
            await verifyConsistencyProofRFC9162({ ...input, proof: [...proof].reverse() })
          ).toBe(false)
      })
    }
  }
  it('checks a generated demonstration proof against both roots, not just old subtree membership', async () => {
    const old = await buildMerkleTree(SAMPLE_CERTS.slice(0, 4))
    const next = await buildMerkleTree(SAMPLE_CERTS.slice(0, 8))
    expect((await getConsistencyProofRFC9162(old.levels, next.levels)).valid).toBe(true)
    const altered = structuredClone(next.levels)
    altered[altered.length - 1][0].hash = '00'.repeat(32)
    expect((await getConsistencyProofRFC9162(old.levels, altered)).valid).toBe(false)
    await expect(getConsistencyProofRFC9162(next.levels, old.levels)).rejects.toThrow(/size order/)
  })
  it('rejects invalid sizes and malformed hashes', async () => {
    const [oldSize, newSize, oldRoot, newRoot, proof] = referenceProofs[1]
    for (const size of [0, -1, 1.5, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) {
      expect(
        await verifyConsistencyProofRFC9162({ oldSize: size, newSize, oldRoot, newRoot, proof })
      ).toBe(false)
    }
    expect(
      await verifyConsistencyProofRFC9162({ oldSize, newSize, oldRoot, newRoot, proof: ['zz'] })
    ).toBe(false)
  })
})
